-- Add verified ingredient provenance and per-user routine storage.
alter table public.products add column if not exists ingredient_source_url text;
create table if not exists public.user_routines (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 morning jsonb not null default '[]'::jsonb, evening jsonb not null default '[]'::jsonb,
 skin_type text, concern text, budget text, sandwich_mode boolean not null default false,
 updated_at timestamptz not null default now(), unique(user_id)
);
alter table public.user_routines enable row level security;
drop policy if exists "Users manage own routines" on public.user_routines;
create policy "Users manage own routines" on public.user_routines for all using (auth.uid()=user_id) with check (auth.uid()=user_id);

-- Keep one saved check-in per product and check-in type per calendar day.
alter table public.check_ins add column if not exists check_in_date date not null default current_date;
create unique index if not exists check_ins_one_per_day on public.check_ins(user_product_id,check_in_type,check_in_date);
drop policy if exists "Users manage own check-ins" on public.check_ins;
drop policy if exists "Users manage check-ins for own products" on public.check_ins;
create policy "Users manage check-ins for own products" on public.check_ins for all
using (auth.uid()=user_id and exists (select 1 from public.user_products up where up.id=user_product_id and up.user_id=auth.uid()))
with check (auth.uid()=user_id and exists (select 1 from public.user_products up where up.id=user_product_id and up.user_id=auth.uid()));

-- Reviews become verified only when the user's own linked product has passed Day 14.
drop policy if exists "Users write own reviews" on public.reviews;
create policy "Users write verified-test reviews" on public.reviews for insert with check (
 auth.uid()=user_id and exists (
   select 1 from public.user_products up where up.id=user_product_id and up.user_id=auth.uid()
     and up.product_id=reviews.product_id and up.patch_test_status='Passed' and up.patch_day>=14
 )
);
drop policy if exists "Users update own reviews" on public.reviews;
create policy "Users edit own reviews" on public.reviews for update using (auth.uid()=user_id) with check (auth.uid()=user_id);
create or replace function public.mark_verified_review() returns trigger language plpgsql security invoker set search_path = '' as $$
begin
  if not exists (
    select 1 from public.user_products up where up.id=new.user_product_id and up.user_id=new.user_id
    and up.product_id=new.product_id and up.patch_test_status='Passed' and up.patch_day>=14
  ) then raise exception 'A completed 14-day patch test is required to review this product'; end if;
  new.is_verified_test := true;
  if tg_op='INSERT' then new.status := 'Pending'; end if;
  if tg_op='UPDATE' and auth.uid()=old.user_id then
    new.status := old.status;
    new.is_verified_test := old.is_verified_test;
  end if;
  return new;
end;
$$;
drop trigger if exists reviews_require_test on public.reviews;
create trigger reviews_require_test before insert or update on public.reviews for each row execute function public.mark_verified_review();

